 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    line = next((v for row in g for v in row if row.count(v) > w // 2), None)
    if line is None:
        return g
    # The background is the most common color; the frame is the other color.
    from collections import Counter
    counts = Counter(v for row in g for v in row)
    frame = max(counts, key=counts.get)
    bg = min(counts, key=counts.get)
    # Each outlined U has vertical sides and a bottom bar. A vertical stem
    # above its opening marks the center column to color.
    for bottom in range(h - 1, 1, -1):
        for left in range(w):
            if g[bottom][left] != frame:
                continue
            for right in range(left + 2, w):
                if g[bottom][right] != frame or any(g[bottom][c] != frame for c in range(left, right + 1)):
                    continue
                if right - left < 2 or (right - left) % 2:
                    continue
                center = (left + right) // 2
                if any(g[r][left] != frame or g[r][right] != frame for r in range(bottom)):
                    continue
                # Require a stem of frame color immediately above the opening.
                if not any(g[r][center] == frame for r in range(bottom)):
                    continue
                # Paint the axis through the interior, starting at its opening;
                # exclude the U's bottom edge. This includes the gap in the
                # long transverse divider.
                start = next((r for r in range(bottom) if g[r][center] != frame), None)
                if start is None:
                    continue
                for r in range(start, bottom):
                    if g[r][center] == bg:
                        g[r][center] = 4
                # Don't repeatedly interpret subsegments of the same bottom.
                break
    return g
